Reg_Q_Table reg_q_table_create( UInt8 q_free_size )
{
    Reg_Q_Table reg_q_table = (Reg_Q_Table)reg_table_build( REG_ATOMIC_USE_RES , sizeof( struct s_Reg_Q_Table ));
    
    reg_q_table->q_free = exec_q_free_create( q_free_size )  ; 

	reg_q_table->mode = 0xFFFFFFFF ;

    reg_q_table->ram_entry = NULL;
        
    return reg_q_table ;
}

